SELECT ?film (MIN(?bdate) AS ?oldestBirth) WHERE {
  VALUES ?film { dbr:Aatma_Gowravam dbr:Vitti_Dandu }
  ?film ?p ?producer .
  FILTER(?p IN (dbo:producer, dbp:producer))
  FILTER(isIRI(?producer))
  ?producer dbo:birthDate ?bdate .
} GROUP BY ?film
ORDER BY ?oldestBirth
LIMIT 1

